# Surah Hud (chapter 11) — part 12: ayat 111-120 (IDs 1584-1593)
SURAH = 11

ENTRIES = {
1584: (
"اور — بے شک — سب — کو — تمہارا رب — ان — کے اعمال — کا پورا بدلہ — دے گا — بے شک — وہ — ان — کے — اعمال — سے — باخبر — ہے",
"""۱۔ اللہ — سب کو — ان کے اعمال کا پورا بدلہ — دے گا۔
۲۔ ’’وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَالَهُمْ إِنَّهُ بِمَا يَعْمَلُونَ خَبِيرٌ‘‘ — اور — بے شک — سب — کو — تمہارا رب — ان — کے اعمال — کا پورا بدلہ — دے گا — بے شک — وہ — ان — کے — اعمال — سے — باخبر — ہے — یعنی بے شک — سب — کو — تمہارا رب — ان کے اعمال — کا پورا — بدلہ — دے گا — بے شک — وہ — ان کے — اعمال — سے باخبر — ہے۔
۳۔ عملی سبق: اللہ — ہر عمل کو دیکھتا ہے؛ کسی عمل — کا بدلہ — کم نہیں ہوگا۔"""
),
1585: (
"پس — قائم — رہو — جیسے — آپؐ — کو — حکم دیا گیا — اور — وہ — جو — آپؐ — کے ساتھ — توبہ — کرتے ہیں — اور — تم — سرکشی — نہ کرو — بے شک — وہ — تمہارے — اعمال — پر — دیکھنے والا — ہے",
"""۱۔ استقامت — ہے — حکم — اور — مبالغہ — نہیں۔
۲۔ ’’فَاسْتَقِمْ كَمَا أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ‘‘ — پس — قائم — رہو — جیسے — آپؐ — کو — حکم دیا گیا — اور — وہ — جو — آپؐ — کے ساتھ — توبہ — کرتے ہیں — اور — تم — سرکشی — نہ کرو — بے شک — وہ — تمہارے — اعمال — پر — دیکھنے والا — ہے — یعنی پس — استقامت — اختیار کرو — جیسے — آپؐ کو حکم دیا گیا — اور وہ جو آپؐ کے ساتھ — توبہ کرتے ہیں — اور — تم — سرکشی — نہ کرو — بے شک — وہ — تمہارے — اعمال — پر — دیکھنے والا — ہے۔
۳۔ عملی سبق: استقامت — حکم ہے؛ سرکشی — ہلاکت — ہے۔"""
),
1586: (
"اور — ان — لوگوں کی طرف — نہ — جھکو — جنہوں نے — ظلم کیا — کہ — تمہیں — آگ چھو — لے — اور — اللہ کے سوا — تمہارا — کوئی — مددگار — نہیں — پھر — تم — نصرت — نہیں — پاؤں گے",
"""۱۔ ظالموں کی طرف — جھکنا — آگ میں گرفت — کا سبب۔
۲۔ ’’وَلَا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ وَمَا لَكُم مِّن دُونِ اللَّهِ مِنْ أَوْلِيَاءَ ثُمَّ لَا تُنصَرُونَ‘‘ — اور — ان — لوگوں کی طرف — نہ — جھکو — جنہوں نے — ظلم کیا — کہ — تمہیں — آگ چھو — لے — اور — اللہ کے سوا — تمہارا — کوئی — مددگار — نہیں — پھر — تم — نصرت — نہیں — پاؤں گے — یعنی ان لوگوں کی طرف — نہ جھکو — جنہوں نے ظلم کیا — کہ تمہیں — آگ — چھو — لے — اور اللہ کے سوا — تمہارا — کوئی مددگار — نہیں — پھر — تم — نصرت — نہیں پاؤں گے۔
۳۔ عملی سبق: ظالموں سے — تعاون — آگ — کا خطرہ — ہے۔"""
),
1587: (
"اور — روز — کی دونوں اطراف — اور — رات کے — کچھ حصے — میں — نماز — قائم کرو — بے شک — نیکیاں — گناہ — کو — مٹا — دیتی ہیں — یہ — نصیحت — ہے — یاد — کرنے والوں — کے لیے",
"""۱۔ دن کے دو سروں — اور رات — کی — کچھ — ہزاعوں — میں — نماز۔
۲۔ ’’وَأَقِمِ الصَّلَاۃَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِّنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّاكِرِينَ‘‘ — اور — روز — کی دونوں اطراف — اور — رات کے — کچھ حصے — میں — نماز — قائم کرو — بے شک — نیکیاں — گناہ — کو — مٹا — دیتی ہیں — یہ — نصیحت — ہے — یاد — کرنے والوں — کے لیے — یعنی دن کی دونوں — اطراف اور رات کے کچھ حصوں — میں — نماز قائم کرو؛ بے شک — نیکیاں — گناہوں — کو — مٹا دیتی ہیں؛ یہ — نصیحت — نصیحت — لینے والوں — کے لیے — ہے۔
۳۔ عملی سبق: نماز — پابندی — سے — پڑھو؛ نیکیاں — گناہ — کو — مٹا — دیتی ہیں۔"""
),
1588: (
"اور — صبر — کرو — بے شک — اللہ — نیکوکاروں — کا اجر — ضائع — نہیں کرتا",
"""۱۔ صبر — نیکوکاروں — کے اجر — کو محفوظ — رکھتا ہے۔
۲۔ ’’وَاصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ‘‘ — اور — صبر — کرو — بے شک — اللہ — نیکوکاروں — کا اجر — ضائع — نہیں کرتا — یعنی صبر کرو — بے شک — اللہ — نیکوکاروں — کا — اجر — ضائع — نہیں کرتا۔
۳۔ عملی سبق: صبر — اللہ کی رضا اور اجر — کا — ذریعہ — ہے۔"""
),
1589: (
"پس — کیوں نہ — تم — سے پہلے — گزشتہ — صدیوں — میں — سے — کچھ — ایسے — نیک لوگ — ہوئے — جو — زمین — میں فساد — سے — روکتے تھے — مگر — تھوڑی — تعداد میں سے — جنہیں — ہم نے — نجات دی — اور — ان — لوگوں نے — جنہوں نے — ظلم کیا — وہ — چیز — جس — میں — انہیں — خوشحال — کیا گیا تھا — اس — کی — پیروی — کی — اور — وہ — مجرم — تھے",
"""۱۔ گزشتہ صدیاں — میں — فساد — روکنے والے — بہت — کم — تھے۔
۲۔ ’’فَلَوْلَا كَانَ مِنَ الْقُرُونِ مِن قَبْلِكُمْ أُولُو بَقِيَّۃٍ يَنْهَوْنَ عَنِ الْفَسَادِ فِي الْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَاتَّبَعَ الَّذِينَ ظَلَمُوا مَا أُتْرِفُوا فِيهِ وَكَانُوا مُجْرِمِينَ‘‘ — پس — کیوں نہ — تم — سے پہلے — گزشتہ — صدیوں — میں — سے — کچھ — ایسے — نیک لوگ — ہوئے — جو — زمین — میں فساد — سے — روکتے تھے — مگر — تھوڑی — تعداد میں سے — جنہیں — ہم نے — نجات دی — اور — ان — لوگوں نے — جنہوں نے — ظلم کیا — وہ — چیز — جس — میں — انہیں — خوشحال — کیا گیا تھا — اس — کی — پیروی — کی — اور — وہ — مجرم — تھے — یعنی تم — سے پہلے — صدیوں — میں — فساد — سے روکنے والے — بہت کم — تھے — جن — کو — ہم — نے نجات دی؛ اور ظالموں — نے — ان — کی خوشحالی — کی پیروی کی — اور وہ — مجرم تھے۔
۳۔ عملی سبق: فساد — روکنے — والے — بہت — کم — ہیں — ہمت — کرو۔"""
),
1590: (
"اور — تمہارا — رب — کسی — بستی — کو — ظلم — سے — ہلاک — نہیں کرے گا — جبکہ — اس — کے — اہل — اصلاح — کرنے والے — ہوں",
"""۱۔ اللہ — بستی — جو اصلاح کرے — اسے ظلم سے — ہلاک — نہیں کرتا۔
۲۔ ’’وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ‘‘ — اور — تمہارا — رب — کسی — بستی — کو — ظلم — سے — ہلاک — نہیں کرے گا — جبکہ — اس — کے — اہل — اصلاح — کرنے والے — ہوں — یعنی تمہارا — رب — کسی — بستی — کو — ظلم — سے — ہلاک — نہیں کرے گا — جبکہ — اس کے اہل — اصلاح — کرنے والے — ہوں۔
۳۔ عملی سبق: معاشرہ — میں — اصلاح — کی روایت — بقا کا ضامن — ہے۔"""
),
1591: (
"اور — اگر — تمہارا رب چاہتا — تو — لوگوں — کو — ایک — امت — بنا دیتا — لیکن — وہ — مختلف — ہوتے رہیں گے",
"""۱۔ اللہ — نے — چاہا ہو — تو — سب — ایک — امت — ہوتے؛ اختلاف — مشیتِ الٰہی — سے۔
۲۔ ’’وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّۃً وَاحِدَۃً وَلَا يَزَالُونَ مُخْتَلِفِينَ‘‘ — اور — اگر — تمہارا رب چاہتا — تو — لوگوں — کو — ایک — امت — بنا دیتا — لیکن — وہ — مختلف — ہوتے رہیں گے — یعنی اگر تمہارا رب — چاہتا — تو لوگوں — کو ایک امت — بنا دیتا — لیکن — وہ — مختلف — ہوتے رہیں گے۔
۳۔ عملی سبق: اختلاف — آزمائش ہے؛ توازن — اور — ہدایت — کی تلاش — کریں۔"""
),
1592: (
"مگر — وہ — جن — پر — تمہارا رب مہربان ہوا — اور — اسی — کے لیے — اس — نے — انہیں — پیدا کیا — اور — تمہارے رب کی بات پوری ہو گئی — کہ — میں — جہنم کو — جنات اور انسان — سب سے — بھر دوں گا",
"""۱۔ رحمت — والے — استثناء؛ جہنم کا بھرنا — ثابت۔
۲۔ ’’إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَۃُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّۃِ وَالنَّاسِ أَجْمَعِينَ‘‘ — مگر — وہ — جن — پر — تمہارا رب مہربان ہوا — اور — اسی — کے لیے — اس — نے — انہیں — پیدا کیا — اور — تمہارے رب کی بات پوری ہو گئی — کہ — میں — جہنم کو — جنات اور انسان — سب سے — بھر دوں گا — یعنی مگر — جن — پر تمہارا — رب — مہربان ہوا — اور اسی کے لیے — اس — نے — انہیں پیدا کیا — اور تمہارے رب کی بات پوری — ہو گئی — کہ — میں — جہنم کو — جنات اور انسان — سب — سے بھر — دوں گا۔
۳۔ عملی سبق: رحمت — والے — مستثنیٰ — ہیں؛ عمل — کرو — تاکہ — رحمت — شامل — ہو۔"""
),
1593: (
"اور — ہم — آپؐ — پر — رسولوں کی خبروں — میں سے — ہر چیز — سناتے ہیں — تاکہ — اس — سے — ہم — آپؐ — کا دل — مضبوط — کریں — اور — اس میں — آپ کے پاس — حق — پہنچا — اور — نصیحت — اور — مؤمنوں — کے لیے — یاد دہانی",
"""۱۔ رسولوں کے واقعات — نبیؐ — کے دل — کو — مضبوط — کرتے ہیں۔
۲۔ ’’وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنبَاءِ الرُّسُلِ مَا نُثَبِّتُ بِهِ فُؤَادَكَ وَجَاءَكَ فِي هَٰذِهِ الْحَقُّ وَمَوْعِظَۃٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ‘‘ — اور — ہم — آپؐ — پر — رسولوں کی خبروں — میں سے — ہر چیز — سناتے ہیں — تاکہ — اس — سے — ہم — آپؐ — کا دل — مضبوط — کریں — اور — اس میں — آپ کے پاس — حق — پہنچا — اور — نصیحت — اور — مؤمنوں — کے لیے — یاد دہانی — یعنی ہم — آپؐ کو رسولوں کی — خبریں — سناتے ہیں — تاکہ — اس — سے ہم آپؐ کا دل — مضبوط — کریں — اور — اس میں آپ کے پاس — حق — پہنچا — اور — نصیحت — اور — مؤمنوں — کی یاد دہانی۔
۳۔ عملی سبق: قرآن کے واقعات — دل کی مضبوطی — کا — ذریعہ — ہیں۔"""
),
}
